/**
 * @file    svpwm.c
 * @brief   SVPWM implementation for XMC4200 edge-aligned PWM
 * @version 1.0
 * @date    2024-01-15
 *
 * This module implements Space Vector PWM for a three-phase voltage source inverter
 * optimized for the XMC4200 CCU8 peripheral in edge-aligned (sawtooth) PWM mode.
 *
 * The implementation accounts for CCU8-specific hardware behavior where T0 is
 * effectively split into 4 parts due to shadow register double-buffering.
 */

#include <math.h>
#include <stdint.h>
#include <stdlib.h>

/* Include the header */
#include "svpwm.h"

/**
 * @brief Lookup table for sector determination
 * 
 * Maps the 3-bit code N (0-7) to sector number (1-6).
 * N = 4*C + 2*B + A, where:
 *   A = 1 if Vbeta > 0
 *   B = 1 if (sqrt(3)*Valpha - Vbeta)/2 > 0
 *   C = 1 if (-sqrt(3)*Valpha - Vbeta)/2 > 0
 */
static const uint8_t g_sector_table[8] = {
    0, 1, 2, 1, 3, 2, 4, 5  /* Index N=0-7 maps to sector */
};

/**
 * @brief Determine SVPWM sector from alpha-beta voltage components
 * 
 * Uses the three-variable sector determination method.
 * The voltage vector is divided into 6 sectors of 60 degrees each.
 * 
 * @param Valpha Alpha component of voltage vector (Volts)
 * @param Vbeta  Beta component of voltage vector (Volts)
 * @return Sector number (1-6)
 */
static uint8_t svpwm_get_sector(float Valpha, float Vbeta)
{
    /* Calculate the three reference variables for sector determination */
    const float Vref1 = Vbeta;
    const float Vref2 = (SQRT3 * Valpha - Vbeta) * 0.5f;
    const float Vref3 = (-SQRT3 * Valpha - Vbeta) * 0.5f;

    /* Determine 3-bit code: A=Vref1>0, B=Vref2>0, C=Vref3>0 */
    const uint8_t A = (Vref1 > 0.0f) ? 1 : 0;
    const uint8_t B = (Vref2 > 0.0f) ? 1 : 0;
    const uint8_t C = (Vref3 > 0.0f) ? 1 : 0;

    /* Convert to N = 4*C + 2*B + A */
    const uint8_t N = (4 << C) | (2 << B) | A;

    /* Map N to sector using lookup table */
    uint8_t sector = g_sector_table[N];

    /* Ensure sector is in valid range 1-6 (index 1-6 in table) */
    if (sector == 0) sector = 1;
    if (sector > 6) sector = 6;

    return sector;
}

/**
 * @brief Calculate SVPWM compare values for edge-aligned PWM mode
 *
 * This function computes the three-phase PWM compare values from the alpha-beta
 * voltage reference vector using SVPWM algorithm adapted for CCU8 edge-aligned mode.
 *
 * @param Valpha Alpha component of voltage reference (Volts)
 * @param Vbeta  Beta component of voltage reference (Volts)
 * @param output Pointer to PWMCompare_t structure to store results
 *
 * Algorithm Steps:
 *
 * 1. Sector Determination:
 *    Determine which of the 6 sectors the voltage vector falls into (1-6).
 *    Uses the three-variable method based on Vref1, Vref2, Vref3.
 *
 * 2. Calculate Intermediate Values:
 *    X = (sqrt(3) / VDC) * Vbeta * PWM_PERIOD
 *    Y = (sqrt(3) / VDC) * (sqrt(3)/2 * Valpha + 0.5 * Vbeta) * PWM_PERIOD
 *    Z = (sqrt(3) / VDC) * (-sqrt(3)/2 * Valpha + 0.5 * Vbeta) * PWM_PERIOD
 *
 *    These formulas convert alpha-beta voltage to dwell times in PWM periods.
 *    The factor sqrt(3) accounts for the geometry of the voltage space vector.
 *
 * 3. Calculate Dwell Times:
 *    Based on the sector, assign T1 and T2 from X, Y, Z:
 *      Sector 1: T1 = Y, T2 = X
 *      Sector 2: T1 = X, T2 = Z
 *      Sector 3: T1 = Z, T2 = -X
 *      Sector 4: T1 = -X, T2 = Z
 *      Sector 5: T1 = -Z, T2 = X
 *      Sector 6: T1 = X, T2 = -Z
 *
 * 4. Calculate Zero Vector Time:
 *    T0 = PWM_PERIOD - T1 - T2
 *    If T1 + T2 > PWM_PERIOD, the reference is in overmodulation region.
 *    In this case, scale T1 and T2 proportionally to fit within PWM_PERIOD.
 *
 * 5. T0 Distribution (CCU8 Edge-Aligned Correction):
 *    Standard edge-aligned PWM splits T0 into two halves (T0/2 at start, T0/2 at end).
 *    However, CCU8 hardware has shadow register double-buffering and dead-time insertion
 *    that effectively split T0 into 4 equal parts (T0/4).
 *
 *    For each sector, compare values are assigned as:
 *      - One phase gets: T_active1 + T_active2 + T0/4
 *      - One phase gets: T_active2 + T0/4
 *      - One phase gets: T0/4
 *
 *    The specific assignment per sector is:
 *      Sector 1: cmp_u = T1 + T2 + T0/4, cmp_v = T2 + T0/4, cmp_w = T0/4
 *      Sector 2: cmp_u = T1 + T0/4, cmp_v = T1 + T2 + T0/4, cmp_w = T0/4
 *      Sector 3: cmp_u = T0/4, cmp_v = T1 + T2 + T0/4, cmp_w = T2 + T0/4
 *      Sector 4: cmp_u = T0/4, cmp_v = T1 + T0/4, cmp_w = T1 + T2 + T0/4
 *      Sector 5: cmp_u = T2 + T0/4, cmp_v = T0/4, cmp_w = T1 + T2 + T0/4
 *      Sector 6: cmp_u = T1 + T2 + T0/4, cmp_v = T0/4, cmp_w = T2 + T0/4
 *
 * 6. Clamp to Valid Range:
 *    Compare values are clamped to [0, PWM_PERIOD] to ensure valid PWM operation.
 *    Zero vector (Valpha=0, Vbeta=0) produces 50% duty on all phases (cmp = 500).
 */
void svpwm_calculate(float Valpha, float Vbeta, PWMCompare_t *output)
{
    /* CCU8 edge-aligned mode parameters */
    const float scale = SQRT3;  /* Per-unit scaling for CCU8: sqrt(3) */

    /* Calculate intermediate values */
    const float X = (scale * Vbeta * PWM_PERIOD) / VDC;
    const float Y = (scale * (SQRT3 * Valpha * 0.5f + Vbeta * 0.5f) * PWM_PERIOD) / VDC;
    const float Z = (scale * (-SQRT3 * Valpha * 0.5f + Vbeta * 0.5f) * PWM_PERIOD) / VDC;

    /* Determine sector */
    uint8_t sector = svpwm_get_sector(Valpha, Vbeta);

    /* Calculate T1, T2 based on sector */
    float T1, T2;

    switch (sector) {
        case 1:
            T1 = Y;
            T2 = X;
            break;
        case 2:
            T1 = X;
            T2 = Z;
            break;
        case 3:
            T1 = Z;
            T2 = -X;
            break;
        case 4:
            T1 = -X;
            T2 = Z;
            break;
        case 5:
            T1 = -Z;
            T2 = X;
            break;
        case 6:
            T1 = X;
            T2 = -Z;
            break;
        default:
            /* Outside linear range or quadrant 4 - fallback */
            T1 = 0.0f;
            T2 = 0.0f;
            break;
    }

    /* Clamp T1 and T2 to non-negative */
    if (T1 < 0.0f) T1 = 0.0f;
    if (T2 < 0.0f) T2 = 0.0f;

    /* Calculate T0 (zero vector time) */
    const float T0 = PWM_PERIOD - T1 - T2;

    /* Apply T0 split for CCU8 edge-aligned mode */
    /* T0 is split into 4 parts due to shadow register double-buffering */
    const float T0_4 = T0 / 4.0f;

    /* Calculate phase timings based on sector and T0 distribution */
    float Ta, Tb, Tc;

    switch (sector) {
        case 1:
            Ta = T1 + T2 + T0_4;
            Tb = T2 + T0_4;
            Tc = T0_4;
            break;
        case 2:
            Ta = T1 + T0_4;
            Tb = T1 + T2 + T0_4;
            Tc = T0_4;
            break;
        case 3:
            Ta = T0_4;
            Tb = T1 + T2 + T0_4;
            Tc = T2 + T0_4;
            break;
        case 4:
            Ta = T0_4;
            Tb = T1 + T0_4;
            Tc = T1 + T2 + T0_4;
            break;
        case 5:
            Ta = T2 + T0_4;
            Tb = T0_4;
            Tc = T1 + T2 + T0_4;
            break;
        case 6:
            Ta = T1 + T2 + T0_4;
            Tb = T0_4;
            Tc = T2 + T0_4;
            break;
        default:
            /* Zero vector case: all phases at 50% duty */
            Ta = (float)PWM_HALF_PERIOD;
            Tb = (float)PWM_HALF_PERIOD;
            Tc = (float)PWM_HALF_PERIOD;
            break;
    }

    /* Clamp all timings to valid range [0, PWM_PERIOD] */
    if (Ta < 0.0f) Ta = 0.0f;
    if (Tb < 0.0f) Tb = 0.0f;
    if (Tc < 0.0f) Tc = 0.0f;
    if (Ta > (float)PWM_PERIOD) Ta = (float)PWM_PERIOD;
    if (Tb > (float)PWM_PERIOD) Tb = (float)PWM_PERIOD;
    if (Tc > (float)PWM_PERIOD) Tc = (float)PWM_PERIOD;

    /* Convert to compare values and round */
    output->cmp_u = (uint16_t)(Ta + 0.5f);
    output->cmp_v = (uint16_t)(Tb + 0.5f);
    output->cmp_w = (uint16_t)(Tc + 0.5f);

    /* Clamp to valid range [0, PWM_PERIOD] */
    if (output->cmp_u > PWM_PERIOD) output->cmp_u = PWM_PERIOD;
    if (output->cmp_v > PWM_PERIOD) output->cmp_v = PWM_PERIOD;
    if (output->cmp_w > PWM_PERIOD) output->cmp_w = PWM_PERIOD;
    if (output->cmp_u < 0) output->cmp_u = 0;
    if (output->cmp_v < 0) output->cmp_v = 0;
    if (output->cmp_w < 0) output->cmp_w = 0;
}
