#include <math.h>
#include <stdint.h>

/* PWM parameters from motor_config and CCU8 peripheral spec */
#define PWM_PERIOD      1000U
#define PWM_HALF_PERIOD 500U
#define VDC             310.0f
#define SQRT3           1.7320508075688772f

/* Output structure for PWM compare values */
typedef struct {
    uint16_t cmp_u;
    uint16_t cmp_v;
    uint16_t cmp_w;
} PWMCompare_t;

/**
 * @brief Determine SVPWM sector from alpha-beta voltage components
 * 
 * The 6 sectors are defined by 60-degree intervals:
 * - Sector 1: 0 to 60 degrees
 * - Sector 2: 60 to 120 degrees
 * - Sector 3: 120 to 180 degrees
 * - Sector 4: 180 to 240 degrees
 * - Sector 5: 240 to 300 degrees
 * - Sector 6: 300 to 360 (or 0) degrees
 * 
 * @param Valpha Alpha component of voltage vector (Volts)
 * @param Vbeta  Beta component of voltage vector (Volts)
 * @return Sector number (0-6)
 */
static int svpwm_determine_sector(float Valpha, float Vbeta)
{
    /* Calculate angle of the voltage vector in degrees */
    double angle_rad = atan2(Vbeta, Valpha);
    double angle_deg = angle_rad * 180.0 / M_PI;

    /* Normalize angle to 0-360 range */
    while (angle_deg < 0) angle_deg += 360;
    while (angle_deg >= 360) angle_deg -= 360;

    /* Determine sector based on angle */
    int sector;
    if (angle_deg >= 0 && angle_deg < 60) sector = 1;
    else if (angle_deg >= 60 && angle_deg < 120) sector = 2;
    else if (angle_deg >= 120 && angle_deg < 180) sector = 3;
    else if (angle_deg >= 180 && angle_deg < 240) sector = 4;
    else if (angle_deg >= 240 && angle_deg < 300) sector = 5;
    else if (angle_deg >= 300 && angle_deg < 360) sector = 6;
    else sector = 0;  /* At the origin (zero vector) */

    return sector;
}

/**
 * @brief Calculate SVPWM compare values for edge-aligned PWM mode
 *
 * This function computes the three-phase PWM compare values from the alpha-beta
 * voltage reference vector.
 */
void svpwm_calculate(const float Valpha, const float Vbeta, PWMCompare_t *output)
{
    /* Use the documented scaling from project_settings.yaml: vdc_normalization = 1.7320 (sqrt(3)) */
    /* This gives per-unit voltage conversion */
    const float scale = SQRT3;

    /* Calculate the factor to convert voltage to time units */
    /* time_units = sqrt(3) * voltage / VDC * PWM_PERIOD */
    const float TIME_SCALE = scale * PWM_PERIOD / VDC;

    /* Calculate intermediate values X, Y, Z based on the sector */
    const float X = TIME_SCALE * Vbeta;
    const float Y = TIME_SCALE * (SQRT3 * Valpha * 0.5f + Vbeta * 0.5f);
    const float Z = TIME_SCALE * (-SQRT3 * Valpha * 0.5f + Vbeta * 0.5f);

    /* Determine sector */
    const int sector = svpwm_determine_sector(Valpha, Vbeta);

    /* Calculate dwell times T1 and T2 based on sector */
    float T1, T2;

    switch (sector) {
        case 1:
            /* Sector 1: vectors V1 and V2 */
            T1 = Y;
            T2 = X;
            break;
        case 2:
            /* Sector 2: vectors V2 and V4 (using X and -Y equivalent to Z) */
            T1 = X;
            T2 = -Z;
            break;
        case 3:
            /* Sector 3: vectors V4 and V5 */
            T1 = -Z;
            T2 = Y;
            break;
        case 4:
            /* Sector 4: vectors V5 and V6 */
            T1 = Y;
            T2 = -X;
            break;
        case 5:
            /* Sector 5: vectors V6 and V1 */
            T1 = -X;
            T2 = Z;
            break;
        case 6:
            /* Sector 6: vectors V1 and V6 (but V1 is larger) */
            T1 = X;
            T2 = -Z;
            break;
        case 0:
            /* Zero sector: equal distribution */
            T1 = 0;
            T2 = 0;
            break;
        default:
            /* Fallback for invalid input */
            T1 = 0;
            T2 = 0;
            break;
    }

    /* Clamp T1 and T2 to non-negative */
    if (T1 < 0.0f) T1 = 0.0f;
    if (T2 < 0.0f) T2 = 0.0f;

    /* Calculate T0 (zero vector time) */
    const float T0 = PWM_PERIOD - T1 - T2;

    /* Clamp T0 to valid range */
    if (T0 < 0.0f) T0 = 0.0f;
    if (T0 > PWM_PERIOD) T0 = PWM_PERIOD;

    /*
     * CCU8 Edge-Aligned T0 Distribution
     * Due to shadow register double-buffering and hardware dead-time,
     * T0 is effectively split into 4 parts (T0/4).
