    const float T0_split = T0 / 4.0f;

    /* Calculate phase timings based on sector */
    float Ta, Tb, Tc;

    switch (sector) {
        case 0:
            /* Zero sector: 50% duty on all phases */
            Ta = (float)PWM_HALF_PERIOD;
            Tb = (float)PWM_HALF_PERIOD;
            Tc = (float)PWM_HALF_PERIOD;
            break;

        case 1:
            /* Sector 1: U phase has most duty, W phase has least */
            Ta = T1 + T2 + T0_split;
            Tb = T2 + T0_split;
            Tc = T0_split;
            break;

        case 2:
            /* Sector 2: V phase has most duty */
            Ta = T1 + T0_split;
            Tb = T1 + T2 + T0_split;
            Tc = T0_split;
            break;

        case 3:
            /* Sector 3: V phase has most duty */
            Ta = T0_split;
            Tb = T1 + T2 + T0_split;
            Tc = T2 + T0_split;
            break;

        case 4:
            /* Sector 4: W phase has most duty */
            Ta = T0_split;
            Tb = T1 + T0_split;
            Tc = T1 + T2 + T0_split;
            break;

        case 5:
            /* Sector 5: W phase has most duty */
            Ta = T2 + T0_split;
            Tb = T0_split;
            Tc = T1 + T2 + T0_split;
            break;

        case 6:
            /* Sector 6: U phase has most duty */
            Ta = T1 + T2 + T0_split;
            Tb = T0_split;
            Tc = T2 + T0_split;
            break;
    }

