    if (Ta < 0.0f) Ta = 0.0f;
    if (Tb < 0.0f) Tb = 0.0f;
    if (Tc < 0.0f) Tc = 0.0f;
    if (Ta > PWM_PERIOD) Ta = PWM_PERIOD;
    if (Tb > PWM_PERIOD) Tb = PWM_PERIOD;
    if (Tc > PWM_PERIOD) Tc = PWM_PERIOD;

    /* Convert to compare values (add PWM_HALF_PERIOD as base for edge-aligned) */
    output->cmp_u = (uint16_t)(Ta + 0.5f);
    output->cmp_v = (uint16_t)(Tb + 0.5f);
    output->cmp_w = (uint16_t)(Tc + 0.5f);

