        strcpy(expected_sector_str, p);
        p = end + 1;

        end = strchr(p, ',');
        if (!end) {
            fprintf(stderr, "Line %d: missing comma\n", line_num);
            continue;
        }
        *end = '\0';
        strcpy(exp_duty_u_str, p);
        p = end + 1;

        end = strchr(p, ',');
        if (!end) {
            fprintf(stderr, "Line %d: missing comma\n", line_num);
            continue;
        }
        *end = '\0';
        strcpy(exp_duty_v_str, p);
        p = end + 1;

        /* Last field is exp_duty_w (remove trailing \r and \n if present) */
        strcpy(exp_duty_w_str, p);
        while (strlen(exp_duty_w_str) > 0 && (exp_duty_w_str[strlen(exp_duty_w_str)-1] == '\r' || 
                                               exp_duty_w_str[strlen(exp_duty_w_str)-1] == '\n')) {
            exp_duty_w_str[strlen(exp_duty_w_str)-1] = '\0';
            strcpy(exp_duty_w_str, p);
        }

        /* Convert to numbers */
        float Valpha = atof(valpha_str);
        float Vbeta = atof(vbeta_str);
        int expected_sector = atoi(expected_sector_str);
        int expected_duty_u = atoi(exp_duty_u_str);
        int expected_duty_v = atoi(exp_duty_v_str);
        int expected_duty_w = atoi(exp_duty_w_str);

        TestResult_t result;
        svpwm_calculate(Valpha, Vbeta, &result);

        /* Check match */
        int matched = 1;
        if (result.sector != expected_sector) matched = 0;
        if (result.cmp_u != expected_duty_u) matched = 0;
        if (result.cmp_v != expected_duty_v) matched = 0;
        if (result.cmp_w != expected_duty_w) matched = 0;

        printf("Test %s: (%.2f, %.2f)\n", test_id, Valpha, Vbeta);
        printf("  Expected: sector=%d, u=%d, v=%d, w=%d\n", expected_sector, expected_duty_u, expected_duty_v, expected_duty_w);
        printf("  Got:      sector=%d, u=%d, v=%d, w=%d\n", result.sector, result.cmp_u, result.cmp_v, result.cmp_w);
        printf("  Match: %s\n", matched ? "PASS" : "FAIL");
        printf("\n");

        if (!matched) {
            errors++;
        }
    }

    fclose(fp);

    printf("\nTotal tests: %d\nErrors: %d\n", line_num, errors);

    return errors;
}
